# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İNCE BAĞIRSAK VİLLUS YAPISI VE BESİNLERİN EMİLİMİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">EMİLİM YÜZEYİNİ ARTIRAN ADAPTASYONLAR</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Kıvrımlı iç mukoza katmanları (Plicae)</text>\n  <text x="35" y="112" font-size="11.2" fill="#1e3a8a">• Parmaksı çıkıntılar: Villuslar (Tümörler)</text>\n  <text x="35" y="136" font-size="11.2" fill="#1e3a8a">• Epitel hücrelerindeki sitoplazmik uzantılar: Mikrovilluslar</text>\n  <text x="35" y="160" font-size="11.2" fill="#1e3a8a">• Emilim mekanizmaları: Pasif taşıma (difüzyon/ozmoz)</text>\n  <text x="35" y="184" font-size="11.2" fill="#1e3a8a">  ve ATP harcanan Aktif Taşıma süreçleri</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">SİNDİRİM KANALINDA EMİLİM BÖLGELERİ</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Ağız ve Mide: Bazı ilaçlar, iyonlar ve az miktarda su</text>\n  <text x="370" y="112" font-size="11.2" fill="#14532d">• İnce Bağırsak: Besin monomerlerinin ve vitaminlerin</text>\n  <text x="370" y="132" font-size="11.2" fill="#14532d">  büyük çoğunluğunun emildiği ana merkezdir.</text>\n  <text x="370" y="156" font-size="11.2" fill="#14532d">• Kalın Bağırsak: Su, elektrolitler (Na, Cl, K) ve</text>\n  <text x="370" y="176" font-size="11.2" fill="#14532d">  mutualist bakterilerin ürettiği B ve K vitaminleri.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Villus ve mikrovilluslar ince bağırsağın emilim yüzeyini yaklaşık 300 metrekareye kadar genişletir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KAN KILCALLARI VE LENF KILCALLARI İLE TAŞINMA YOLLARI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">1. KAN KILCALLARI YOLU (KAPILI DOLAŞIM)</text>\n  <text x="35" y="86" font-size="10.8" fill="#7f1d1d">• Taşınanlar: Glikoz, galaktoz, fruktoz, amino asitler,</text>\n  <text x="35" y="103" font-size="10.8" fill="#7f1d1d">  B ve C vitaminleri, su ve mineraller</text>\n  <text x="35" y="124" font-size="10.8" fill="#7f1d1d">• Villus kan kılcalları → Kapı toplardamarı (Vena porta)</text>\n  <text x="35" y="144" font-size="10.8" fill="#7f1d1d">• Karaciğer → Karaciğer üstü toplardamarı</text>\n  <text x="35" y="164" font-size="10.8" fill="#7f1d1d">• Alt ana toplardamar → Kalbin SAĞ KULAKÇIĞI</text>\n  <text x="35" y="184" font-size="10.8" font-weight="bold" fill="#991b1b">• Karaciğer kan şekerini düzenler ve zehirleri arındırır.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">2. LENF KILCALLARI YOLU (AKKAN DOLAŞIMI)</text>\n  <text x="370" y="86" font-size="10.8" fill="#713f12">• Taşınanlar: Yağ asidi + Gliserol → Şilomikron,</text>\n  <text x="370" y="103" font-size="10.8" fill="#713f12">  yağda çözünen A, D, E, K vitaminleri</text>\n  <text x="370" y="124" font-size="10.8" fill="#713f12">• Lenf kılcalları → Kilus borusu → Peke sarnıcı</text>\n  <text x="370" y="144" font-size="10.8" fill="#713f12">• Göğüs lenf kanalı → Sol köprücük altı toplardamarı</text>\n  <text x="370" y="164" font-size="10.8" fill="#7f1d1d">  (Burada lenf sıvısı ilk kez kana karışır!)</text>\n  <text x="370" y="184" font-size="10.8" font-weight="bold" fill="#854d0e">• Üst ana toplardamar → Kalbin SAĞ KULAKÇIĞI</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Her iki yolla taşınan besinler kalbin sağ kulakçığında ilk kez karşılaşır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">SİNDİRİM SİSTEMİ RAHATSIZLIKLARI VE KORUNMA YOLLARI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">BAŞLICA SİNDİRİM RAHATSIZLIKLARI</text>\n  <text x="35" y="88" font-size="11.2" fill="#581c87">• Reflü: Mide asidinin yemek borusuna geri kaçması</text>\n  <text x="35" y="112" font-size="11.2" fill="#581c87">• Gastrit ve Ülser: Mide mukozası iltihabı ve yarası</text>\n  <text x="35" y="136" font-size="11.2" fill="#581c87">  (Helicobacter pylori bakterisi ve stres etkisi)</text>\n  <text x="35" y="160" font-size="11.2" fill="#581c87">• İshal ve Kabızlık: Su/elektrolit emilimi dengesizliği</text>\n  <text x="35" y="184" font-size="11.2" fill="#581c87">• Çölyak ve Laktoz İntoleransı: Emilim ve enzim kusuru</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">SİNDİRİM SAĞLIĞINI KORUMA İLKELERİ</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Yeterli su tüketimi ve lifli (posali) beslenme</text>\n  <text x="370" y="112" font-size="11.2" fill="#14532d">• Besinleri iyi çiğneme ve ağız-diş hijyenine özen</text>\n  <text x="370" y="136" font-size="11.2" fill="#14532d">• Probiyotik ve fermente gıdalarla mikrobiyotayı koruma</text>\n  <text x="370" y="160" font-size="11.2" fill="#14532d">• Bilinçsiz antibiyotik ve ağrı kesici kullanımından kaçınma</text>\n  <text x="370" y="184" font-size="11.2" fill="#14532d">• Aşırı asitli, baharatlı gıda ve stresten uzak durma</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Diyet lifi (selüloz) insanda sindirilmez ancak mukus salgısını ve peristaltik hareketi uyarır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
